        self.server_host = server_host
        self.server_port = server_port
        self.bot_id = f"bot_{int(time.time())}"
        self.socket = None
        self.running = False

    def connect_to_cc(self):
        """Establish connection to C&C server"""
        try:
            self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.socket.connect((self.server_host, self.server_port))
            print(f"[TRAINING] Bot {self.bot_id} connected to C&C")

            # Send registration
            self.register_with_cc()
            return True

        except Exception as e:
            print(f"[TRAINING] Connection failed: {e}")
            return False

    def register_with_cc(self):
        """Register bot with C&C server"""
        registration_data = {
            'type': 'registration',
            'bot_id': self.bot_id,
            'system_info': {
                'platform': 'training_environment',
                'version': '1.0',
                'capabilities': ['info', 'ping']
            },
            'timestamp': datetime.now().isoformat()
        }

        self.send_message(registration_data)
        response = self.receive_message()

        if response and response.get('status') == 'success':
            print(f"[TRAINING] Registration successful")
        else:
            print(f"[TRAINING] Registration failed")

    def send_message(self, message):
        """Send JSON message to C&C server"""
        try:
            data = json.dumps(message).encode('utf-8')
            self.socket.send(data)
        except Exception as e:
            print(f"[TRAINING] Send error: {e}")

    def receive_message(self):
        """Receive and parse JSON message from C&C"""
        try:
            data = self.socket.recv(4096)
            if data:
                return json.loads(data.decode('utf-8'))
        except Exception as e:
            print(f"[TRAINING] Receive error: {e}")
        return None

    def start_heartbeat(self):
        """Start heartbeat loop to maintain connection"""
        self.running = True

        while self.running:
            try:
                # Send heartbeat
                heartbeat = {
                    'type': 'heartbeat',
                    'bot_id': self.bot_id,
                    'timestamp': datetime.now().isoformat()
                }

                self.send_message(heartbeat)
                response = self.receive_message()

                if response:
                    # Process any commands received
                    commands = response.get('commands', [])
                    for cmd in commands:
                        self.execute_command(cmd)

                time.sleep(10)  # Heartbeat interval

            except Exception as e:
                print(f"[TRAINING] Heartbeat error: {e}")
                break

    def execute_command(self, command):
        """Execute received command and send result"""
        cmd_type = command.get('command')
        cmd_id = command.get('cmd_id')

        print(f"[TRAINING] Executing command: {cmd_type}")

        # Simulate command execution
        if cmd_type == 'info':
            result = "Training bot - system info collected"
        elif cmd_type == 'ping':
            result = "pong"
        else:
            result = f"Unknown command: {cmd_type}"

        # Send result back
        result_message = {
            'type': 'command_result',
            'bot_id': self.bot_id,
            'cmd_id': cmd_id,
            'result': result,
            'timestamp': datetime.now().isoformat()
        }

        self.send_message(result_message)

    def disconnect(self):
        """Clean disconnect from C&C"""
        self.running = False
        if self.socket:
            self.socket.close()
        print(f"[TRAINING] Bot {self.bot_id} disconnected")

### Training Usage Examples

def run_cc_server():
    """Run the C&C server for training"""
    server = EducationalCCServer()
    try:
        server.start_server()
    except KeyboardInterrupt:
        print("\n[TRAINING] Shutting down server...")
        server.cleanup()

def run_bot_client():
    """Run a bot client for training"""
    bot = EducationalBot()

    if bot.connect_to_cc():
        try:
            bot.start_heartbeat()
        except KeyboardInterrupt:
            print(f"\n[TRAINING] Shutting down bot...")
        finally:
            bot.disconnect()

if __name__ == "__main__":
    import sys

    print("="*60)
    print("CYBERSECURITY TRAINING - BOTNET C&C SIMULATION")
    print("WARNING: Educational purposes only!")
    print("="*60)

    if len(sys.argv) > 1 and sys.argv[1] == 'server':
        run_cc_server()
    elif len(sys.argv) > 1 and sys.argv[1] == 'bot':
        run_bot_client()
    else:
        print("Usage:")
        print("  python botnet_training.py server  # Run C&C server")
        print("  python botnet_training.py bot     # Run bot client")
